package com.ravita.organization.api;
import com.ravita.organization.domain.*; import com.ravita.organization.repository.OrganizationRepository; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.net.URI; import java.math.BigDecimal; import java.util.*;
@RestController @RequestMapping("/api/v1/organizations") public class OrganizationController {
 private final OrganizationRepository repository; public OrganizationController(OrganizationRepository repository){this.repository=repository;}
 @PostMapping public ResponseEntity<Organization> create(@Valid @RequestBody OrganizationInput input){validateCapacity(input.type(),input.receivingCapacity());if(repository.existsByDocument(input.document()))throw new DuplicateDocumentException(); Organization o=repository.save(new Organization(input.name(),input.type(),input.document(),input.address(),toCapacity(input.receivingCapacity()))); return ResponseEntity.created(URI.create("/api/v1/organizations/"+o.getId())).body(o);}
 @GetMapping public Page<Organization> list(@RequestParam(defaultValue="1") @Min(1) int page,@RequestParam(defaultValue="20") @Min(1) @Max(100) int size,@RequestParam(required=false) OrganizationType type,@RequestParam(required=false) Boolean active){Pageable p=PageRequest.of(page-1,size,Sort.by(Sort.Direction.DESC,"createdAt").and(Sort.by("id")));if(type!=null&&active!=null)return repository.findByTypeAndActive(type,active,p);if(type!=null)return repository.findByType(type,p);if(active!=null)return repository.findByActive(active,p);return repository.findAll(p);}
 @GetMapping("/{id}") public Organization get(@PathVariable String id){return repository.findById(id).orElseThrow(ResourceNotFoundException::new);}
 @PatchMapping("/{id}") public Organization patch(@PathVariable String id,@Valid @RequestBody OrganizationPatch input){Organization o=repository.findById(id).orElseThrow(ResourceNotFoundException::new);o.patch(input.name(),input.address(),input.active());return repository.save(o);}
 private void validateCapacity(OrganizationType type,List<ReceivingCapacityInput> capacity){if(type==OrganizationType.INSTITUTION && (capacity==null||capacity.isEmpty()))throw new InvalidOrganizationException();if(type==OrganizationType.DONOR && capacity!=null&&!capacity.isEmpty())throw new InvalidOrganizationException();if(capacity!=null){Set<String> keys=new HashSet<>();for(ReceivingCapacityInput item:capacity){if(item.maxQuantity()==null||item.maxQuantity().signum()<=0||!keys.add(item.foodCategory()+":"+item.unit()))throw new InvalidOrganizationException();}}}
 private List<ReceivingCapacity> toCapacity(List<ReceivingCapacityInput> input){return input==null?List.of():input.stream().map(i->new ReceivingCapacity(i.foodCategory(),i.maxQuantity(),i.unit())).toList();}
 public record OrganizationInput(@NotBlank @Size(max=150) String name,@NotNull OrganizationType type,@NotBlank @Pattern(regexp="\\d{14}") String document,@NotNull Address address,List<ReceivingCapacityInput> receivingCapacity){}
 public record OrganizationPatch(@Size(max=150) String name,Address address,Boolean active){}
 public record ReceivingCapacityInput(@NotBlank String foodCategory,@NotNull BigDecimal maxQuantity,@NotBlank String unit){}
}
